function probe(params) {
  return Math.sin(params.x * Math.PI / 180);
}

function draw(ctx, state) {
  const x = state.params.x;
  const a = x * Math.PI / 180;
  const w = state.w, h = state.h;
  const ink = state.dark ? '#dbe3ee' : '#263242';
  const faint = state.dark ? '#526071' : '#d5dbe3';
  const blue = '#2f6fe4', gray = '#9aa4b2';
  ctx.clearRect(0, 0, w, h);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // A pendulum swings through the selected maximum angle.
  const px = w * 0.23, py = h * 0.19;
  const len = Math.min(w * 0.27, h * 0.60);
  const swing = a * Math.cos(state.t * 1.7);
  const bx = px + len * Math.sin(swing);
  const by = py + len * Math.cos(swing);
  ctx.strokeStyle = faint;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(px - len * 0.58, py);
  ctx.lineTo(px + len * 0.58, py);
  ctx.moveTo(px, py);
  ctx.lineTo(px, py + len);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(px, py, len, Math.PI / 2 - a, Math.PI / 2 + a);
  ctx.stroke();
  ctx.strokeStyle = gray;
  ctx.beginPath();
  ctx.moveTo(px, py);
  ctx.lineTo(px, py + len);
  ctx.stroke();
  ctx.strokeStyle = blue;
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(px, py);
  ctx.lineTo(bx, by);
  ctx.stroke();
  ctx.fillStyle = blue;
  ctx.beginPath();
  ctx.arc(bx, by, 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = ink;
  ctx.beginPath();
  ctx.arc(px, py, 4, 0, Math.PI * 2);
  ctx.fill();

  // Compare the exact sine curve with the small-angle straight line.
  const left = w * 0.52, right = w * 0.94;
  const top = h * 0.16, bottom = h * 0.80;
  const gw = right - left, gh = bottom - top;
  const ymax = Math.PI / 2;
  const sx = function(v) { return left + gw * v / (Math.PI / 2); };
  const sy = function(v) { return bottom - gh * v / ymax; };
  ctx.strokeStyle = faint;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(left, top);
  ctx.lineTo(left, bottom);
  ctx.lineTo(right, bottom);
  ctx.stroke();
  ctx.strokeStyle = gray;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(sx(0), sy(0));
  ctx.lineTo(sx(Math.PI / 2), sy(Math.PI / 2));
  ctx.stroke();
  ctx.strokeStyle = blue;
  ctx.lineWidth = 3;
  ctx.beginPath();
  for (let i = 0; i <= 120; i++) {
    const u = (Math.PI / 2) * i / 120;
    const xx = sx(u), yy = sy(Math.sin(u));
    if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
  }
  ctx.stroke();

  const cx = sx(a), exactY = sy(Math.sin(a)), approxY = sy(a);
  ctx.setLineDash([4, 5]);
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = faint;
  ctx.beginPath();
  ctx.moveTo(cx, bottom);
  ctx.lineTo(cx, approxY);
  ctx.stroke();
  ctx.strokeStyle = gray;
  ctx.beginPath();
  ctx.moveTo(left, approxY);
  ctx.lineTo(cx, approxY);
  ctx.stroke();
  ctx.strokeStyle = blue;
  ctx.beginPath();
  ctx.moveTo(left, exactY);
  ctx.lineTo(cx, exactY);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = gray;
  ctx.beginPath();
  ctx.arc(cx, approxY, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = blue;
  ctx.beginPath();
  ctx.arc(cx, exactY, 6, 0, Math.PI * 2);
  ctx.fill();

  ctx.font = '14px sans-serif';
  ctx.fillStyle = blue;
  ctx.fillText('sin x', left + 8, top + 20);
  ctx.fillStyle = gray;
  ctx.fillText('x', right - 18, top + 20);
  ctx.fillStyle = ink;
  ctx.fillText('angle', (left + right) / 2 - 18, Math.min(h - 10, bottom + 30));
}

const G=9.81;
function ellipticK(k){
  let a=1,b=Math.sqrt(1-k*k);
  for(let i=0;i<12&&Math.abs(a-b)>1e-14;i++){
    const n=(a+b)/2;b=Math.sqrt(a*b);a=n;
  }
  return Math.PI/(2*a);
}
function realPeriod(L,a){
  return 4*Math.sqrt(L/G)*ellipticK(Math.sin(a/2));
}
function probe(params){
  return realPeriod(params.L_m,params.amplitude_deg*Math.PI/180);
}
function draw(ctx,state){
  const p=state.params,w=state.w,h=state.h,dark=state.dark;
  const fg=dark?'#dce4ef':'#263445',faint=dark?'#536174':'#c6ccd4';
  const blue='#2f6fe4',gray='#9aa4b2',a=p.amplitude_deg*Math.PI/180;
  const T=realPeriod(p.L_m,a),omega=Math.sqrt(G/p.L_m);
  const time=state.t%(2*T),steps=720,dt=time/steps;
  let th=a,om=0;
  for(let i=0;i<steps;i++){
    const k1t=om,k1o=-G/p.L_m*Math.sin(th);
    const k2t=om+k1o*dt/2,k2o=-G/p.L_m*Math.sin(th+k1t*dt/2);
    const k3t=om+k2o*dt/2,k3o=-G/p.L_m*Math.sin(th+k2t*dt/2);
    const k4t=om+k3o*dt,k4o=-G/p.L_m*Math.sin(th+k3t*dt);
    th+=dt*(k1t+2*k2t+2*k3t+k4t)/6;
    om+=dt*(k1o+2*k2o+2*k3o+k4o)/6;
  }
  const predicted=a*Math.cos(omega*time),cx=w/2,top=h*0.14;
  const len=Math.min(h*0.52,w*0.65);
  ctx.clearRect(0,0,w,h);
  ctx.lineCap='round';
  ctx.strokeStyle=faint;ctx.lineWidth=1;
  ctx.beginPath();ctx.moveTo(cx-len*Math.sin(a),top);ctx.lineTo(cx+len*Math.sin(a),top);ctx.stroke();
  ctx.beginPath();ctx.arc(cx,top,4,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
  ctx.setLineDash([5,5]);ctx.strokeStyle=gray;ctx.lineWidth=1.5;
  ctx.beginPath();ctx.moveTo(cx,top);ctx.lineTo(cx+len*Math.sin(predicted),top+len*Math.cos(predicted));ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle=gray;ctx.beginPath();ctx.arc(cx+len*Math.sin(predicted),top+len*Math.cos(predicted),9,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle=blue;ctx.lineWidth=3;
  ctx.beginPath();ctx.moveTo(cx,top);ctx.lineTo(cx+len*Math.sin(th),top+len*Math.cos(th));ctx.stroke();
  ctx.fillStyle=blue;ctx.beginPath();ctx.arc(cx+len*Math.sin(th),top+len*Math.cos(th),12,0,Math.PI*2);ctx.fill();
  const x0=w*0.12,x1=w*0.88,y0=h*0.82,mid=h*0.91;
  ctx.strokeStyle=faint;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x0,mid);ctx.lineTo(x1,mid);ctx.stroke();
  function curve(rule,color,dash){
    ctx.strokeStyle=color;ctx.lineWidth=2;ctx.setLineDash(dash);ctx.beginPath();
    for(let i=0;i<=180;i++){
      const u=i/180,ang=rule?a*Math.cos(omega*u*T):a*Math.cos(2*Math.PI*u);
      const x=x0+(x1-x0)*u,y=mid-ang/a*(mid-y0);
      if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
    }
    ctx.stroke();ctx.setLineDash([]);
  }
  curve(true,gray,[4,4]);curve(false,blue,[]);
}

function probe(params) {
  const m = params.m_kg, k = params.k_Nm, k3 = params.k3_Nm3;
  let x = params.amplitude_m, v = 0;
  const omega0 = Math.sqrt(k / m);
  const dt = 0.005 / omega0;
  let t = 0;
  function acceleration(x) { return -(k * x + k3 * x * x * x) / m; }
  for (let i = 0; i < 1000000; i++) {
    const oldX = x;
    const a1 = v, b1 = acceleration(x);
    const a2 = v + 0.5 * dt * b1, b2 = acceleration(x + 0.5 * dt * a1);
    const a3 = v + 0.5 * dt * b2, b3 = acceleration(x + 0.5 * dt * a2);
    const a4 = v + dt * b3, b4 = acceleration(x + dt * a3);
    x += dt * (a1 + 2 * a2 + 2 * a3 + a4) / 6;
    v += dt * (b1 + 2 * b2 + 2 * b3 + b4) / 6;
    t += dt;
    if (oldX < 0 && x >= 0 && v > 0) {
      const crossing = t - dt + dt * (-oldX) / (x - oldX);
      return 4 * crossing / 3;
    }
  }
  return NaN;
}

function draw(ctx, state) {
  const p = state.params, w = state.w, h = state.h, dark = state.dark;
  const bg = dark ? '#11161d' : '#f7f9fc';
  const line = dark ? '#738096' : '#667085';
  const faint = dark ? '#2c3542' : '#dce2ea';
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);
  const m = p.m_kg, k = p.k_Nm, A = p.amplitude_m;
  const omega = Math.sqrt(k / m);
  const phase = omega * state.t;
  const x = A * Math.cos(phase);
  const cy = h * 0.38;
  const wallX = w * 0.13;
  const restX = w * 0.61;
  const scale = w * 0.25 / Math.max(A, 0.001);
  const massSize = 28 + 10 * Math.cbrt(m);
  const massX = restX + x * scale;

  ctx.strokeStyle = line;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(wallX, cy - 65);
  ctx.lineTo(wallX, cy + 65);
  ctx.stroke();
  ctx.lineWidth = 1;
  for (let y = cy - 60; y < cy + 65; y += 10) {
    ctx.beginPath();
    ctx.moveTo(wallX - 9, y + 8);
    ctx.lineTo(wallX, y);
    ctx.stroke();
  }

  ctx.strokeStyle = '#9aa4b2';
  ctx.setLineDash([5, 5]);
  ctx.strokeRect(massX - massSize / 2, cy - massSize / 2, massSize, massSize);
  ctx.setLineDash([]);

  const springEnd = massX - massSize / 2;
  const coils = 12;
  ctx.strokeStyle = line;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(wallX + 4, cy);
  for (let i = 0; i <= coils * 2; i++) {
    const sx = wallX + 4 + (springEnd - wallX - 4) * i / (coils * 2);
    const sy = cy + (i === 0 || i === coils * 2 ? 0 : (i % 2 ? -13 : 13));
    ctx.lineTo(sx, sy);
  }
  ctx.stroke();

  ctx.fillStyle = '#2f6fe4';
  ctx.fillRect(massX - massSize / 2, cy - massSize / 2, massSize, massSize);
  ctx.strokeStyle = dark ? '#a9c4f5' : '#174fae';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(massX - massSize / 2, cy - massSize / 2, massSize, massSize);

  ctx.strokeStyle = faint;
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 5]);
  ctx.beginPath();
  ctx.moveTo(restX, cy - 80);
  ctx.lineTo(restX, cy + 80);
  ctx.stroke();
  ctx.setLineDash([]);

  const gx = w * 0.1, gw = w * 0.8, gy = h * 0.72, gh = h * 0.17;
  ctx.strokeStyle = faint;
  ctx.beginPath();
  ctx.moveTo(gx, gy);
  ctx.lineTo(gx + gw, gy);
  ctx.stroke();

  function graph(color, dash) {
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash(dash);
    ctx.beginPath();
    for (let i = 0; i <= 140; i++) {
      const u = i / 140;
      const xx = gx + u * gw;
      const yy = gy - gh * Math.cos(phase - 2 * Math.PI * (1 - u));
      if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
    }
    ctx.stroke();
    ctx.setLineDash([]);
  }
  graph('#9aa4b2', [6, 5]);
  graph('#2f6fe4', []);
  ctx.fillStyle = '#2f6fe4';
  ctx.beginPath();
  ctx.arc(gx + gw, gy - gh * Math.cos(phase), 4, 0, 2 * Math.PI);
  ctx.fill();
}
